<h1><?= te('Team communications') ?></h1><p class="sub"><?= te('Private project channels for office teams, supervisors and workers. Use messages to coordinate deployment waves and meeting arrangements.') ?></p>
<div class="grid g2"><div class="card"><h2><?= te('Your channels') ?></h2><?php foreach($channels as $c): ?><p><a href="/comms?channel_id=<?= (int)$c['id'] ?>"><?= e($c['name']) ?></a></p><?php endforeach; ?></div><?php if(can('recruiter')): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="channel"><label><?= te('New channel in selected project') ?></label><input name="name" required maxlength="190"><button class="btn"><?= te('Create channel') ?></button></form><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="member"><input type="hidden" name="channel_id" value="<?= $cid ?>"><label><?= te('Add member to selected channel') ?></label><select name="user_id"><?php foreach($people as $u): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['name']) ?></option><?php endforeach; ?></select><button class="btn"><?= te('Add member') ?></button></form><?php endif; ?></div>
<?php if($allowed): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="message"><input type="hidden" name="channel_id" value="<?= $cid ?>"><label><?= te('Message') ?></label><textarea name="message" maxlength="4000" required></textarea><button class="btn"><?= te('Send to channel') ?></button></form><div class="card"><?php foreach($messages as $m): ?><article><b><?= e($m['name']) ?></b> <span class="muted"><?= e($m['created_at']) ?></span><p><?= nl2br(e($m['message'])) ?></p></article><?php endforeach; ?></div><?php endif; ?>